import random

GROUP = "number_theory"
SKILL = "induction"


def find_max_inclusion_exclusion(target, prime):
    if target == 0:
        return 0

    if target < prime:
        return -1

    max_count = 0

    for i in range(1, target // prime + 1):
        remaining_target = target - i * prime
        count = find_max_inclusion_exclusion(remaining_target, prime)

        if count != -1:
            max_count = max(max_count, count + i)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    prime = rng.randint(5, 20)
    target_value = rng.randint(30, 60)

    answer = find_max_inclusion_exclusion(target_value, prime)

    check = -1
    for i in range(1, target_value // prime + 1):
        remaining_target = target_value - i * prime
        count = find_max_inclusion_exclusion(remaining_target, prime)
        if count != -1:
            check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a sequence of terms where each term is a multiple of a fixed prime number {prime}. The sum of the terms in the sequence is exactly {target_value}. "
        f"What is the maximum number of distinct terms that can be selected such that no term exceeds the target sum {target_value} and the total number of selected terms sums to exactly {target_value}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "combinatorics"
SKILL = "induction"


def find_max_subset_size(n, min_size, max_size):
    if n == 0:
        return 0

    if n < min_size:
        return -1

    max_count = 0

    for subset_size in range(min_size, max_size + 1):
        if subset_size <= n:
            remaining_n = n - subset_size
            count = find_max_subset_size(remaining_n, min_size, subset_size - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_size = rng.randint(3, 10)
    max_size = rng.randint(20, 40)
    n = rng.randint(50, 100)

    answer = find_max_subset_size(n, min_size, max_size)

    check = -1
    for subset_size in range(min_size, max_size + 1):
        if subset_size <= n:
            remaining_n = n - subset_size
            count = find_max_subset_size(remaining_n, min_size, subset_size - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of distinct subsets of a universal set where the size of each subset ranges from {min_size} to {max_size} (inclusive). "
        f"What is the maximum number of distinct subsets of size up to {n} that can be selected such that no subset size exceeds the total {n} and all selected subset sizes sum to exactly {n}? State only the integer."
    )
    return problem, str(answer)

