        if exponent <= n:
            remaining_n = n - exponent
            count = find_max_exponent(remaining_n, min_exp, exponent - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a grid of points where the coordinates range from {min_exp} to {max_exp} (inclusive). "
        f"What is the maximum number of distinct points that can be selected such that no point exceeds the total {n} and all selected points sum to exactly {n}? State only the integer."
    )
